/** What to do with a running backfill. */
export type AccountingBackfillAction =
  | 'Cancel'
  | 'Pause'
  | 'Resume';

/** Where a backfill stands. */
export type AccountingBackfillStatus =
  | 'Cancelled'
  | 'Completed'
  | 'Failed'
  | 'Paused'
  | 'Queued'
  | 'Running';

/** What a phrase or action of the accounting brief leads to. */
export type AccountingBriefingLink =
  /** Promises to pay that lapsed unpaid; one customer's when the segment carries its customerId. */
  | 'BrokenPromise'
  /** Invoices that pass 90 days past due within the week. */
  | 'CrossingNinety'
  /** The invoices in dispute. */
  | 'Disputed'
  /** Invoices still in draft, not yet sent to the customer. */
  | 'Drafts'
  /** Invoices falling due in the next 7 days, worth a reminder before they are late. */
  | 'DueSoon'
  /** Invoices falling due in the next 30 days, when none fall due this week. */
  | 'DueThisMonth'
  /** Collections follow-ups that have come round. */
  | 'FollowUpsDue'
  /** No cash recorded in the last 91 days against what was billed. */
  | 'NoCollections'
  /** The open invoices. */
  | 'OpenInvoices'
  /** The invoices past their due date. */
  | 'Overdue'
  /** The balance more than 90 days past due. */
  | 'PastNinety'
  /** Promises to pay coming due in the next 2 days. */
  | 'PromisesDue'
  /** Short payments leaving small balances open, candidates to write off. */
  | 'ShortPayRemainders'
  /** The customer with the most past due; the segment carries its customerId. */
  | 'TopCustomer'
  /** Cash received and not yet applied to an invoice. */
  | 'UnappliedCash'
  /** Past-due customers with no collections contact in 14 days. */
  | 'Uncontacted';

/** How the link to the accounting system is doing right now. */
export type AccountingConnectionStatus =
  /** Calls succeed. */
  | 'Connected'
  /** The last call failed; Trenova keeps retrying. */
  | 'Degraded'
  /** Someone disconnected it on purpose. */
  | 'Disconnected'
  /** Several calls in a row failed; nothing reaches the books until it recovers. */
  | 'Failing'
  /** The authorization was revoked or expired; someone has to reconnect. */
  | 'Revoked';

/** Which side a fix changes. */
export type AccountingDriftDirection =
  /** Change Trenova to match the accounting system. */
  | 'AdjustTrenova'
  /** Send Trenova's document to the accounting system again. */
  | 'PushTrenovaValue';

/** What a fix made. */
export type AccountingDriftFixObject =
  | 'CreditMemo'
  | 'DebitMemo'
  | 'InvoiceVoid'
  | 'PaymentReversal'
  | 'SyncRecord';

/** How the accounting system and Trenova differ on a document Trenova sent. */
export type AccountingDriftKind =
  /** The total differs. */
  | 'AmountMismatch'
  /** A customer's open balance differs over the documents both sides hold. */
  | 'CustomerBalanceMismatch'
  /** It was deleted in the accounting system. */
  | 'DeletedInProvider'
  /** Trenova voided or reversed it; the accounting system still has it. */
  | 'StatusMismatch'
  /** An account's balance differs from the accounting system's trial balance. */
  | 'TrialBalanceMismatch'
  /** It was voided in the accounting system. */
  | 'VoidedInProvider';

export type AccountingDriftResolution =
  | 'AdjustedTrenova'
  | 'Dismissed'
  | 'NoLongerDiffers'
  | 'PushedTrenovaValue';

export type AccountingDriftStatus =
  | 'Dismissed'
  | 'Open'
  | 'Resolved';

/** Why the last call to the accounting system failed. */
export type AccountingErrorCategory =
  | 'Configuration'
  | 'RateLimited'
  | 'Revoked'
  | 'Transient'
  | 'Unauthorized'
  | 'Unknown';

export type AccountingInboundChangeKind =
  | 'BillPayment'
  | 'CustomerPayment';

/** Why a payment was not applied on its own. */
export type AccountingInboundChangeReason =
  | 'AlreadyPaid'
  | 'ApplyFailed'
  | 'CurrencyMismatch'
  | 'NotTrenovaDocument'
  | 'Overpayment'
  | 'PartialBillPayment'
  | 'PartyMismatch'
  | 'PeriodNotOpen'
  | 'PolicyPropose'
  | 'SentFromTrenova'
  | 'UnknownDocument'
