export type AccountingInboundDocumentKind =
  | 'Bill'
  | 'CreditMemo'
  | 'DebitMemo'
  | 'Invoice'
  | 'Other'
  | 'VendorCredit';

/** What happens to a payment recorded in the accounting system against documents Trenova sent. */
export type AccountingInboundPaymentPolicy =
  /** Payments that match Trenova are applied on their own; the rest wait for a person. */
  | 'Apply'
  /** Payments recorded there are not brought into Trenova. */
  | 'Off'
  /** Each payment waits for a person to apply it in Trenova. */
  | 'Propose';

/** How journal entries are sent in ledger mode. */
export type AccountingLedgerGranularity =
  /** One journal entry for each day, summed per account and customer or vendor. */
  | 'DailySummary'
  /** One journal entry for each one posted in Trenova. */
  | 'Detailed';

export type AccountingMappingFilterInput = {
  requiredOnly?: boolean | null | undefined;
  /** Matches the Trenova label or the chosen record's name. */
  search?: string | null | undefined;
  states?: Array<AccountingMappingState> | null | undefined;
  targetTypes?: Array<AccountingMappingTargetType> | null | undefined;
};

/** Who chose the record a mapping points at. */
export type AccountingMappingSource =
  /** An agent chose it. */
  | 'Agent'
  /** Trenova created the record in the accounting system for it. */
