export type InvoiceScope =
  /** A credit memo, rebill or reversal in a correction chain. */
  | 'Adjustment'
  /** A customer's shipments across a billing period, spanning orders. */
  | 'Consolidated'
  /** A standalone credit or debit memo with no shipment behind it. */
  | 'Memo'
  /** Every billable leg of one order. */
  | 'Order'
  /** One shipment. */
  | 'Shipment';

/** How the lines inside one invoice are organised. Never changes how many there are. */
export type InvoiceSectionKey =
  | 'Destination'
  | 'Origin'
  | 'PONumber'
  | 'Shipment';

export type InvoiceSendStatus =
  | 'Failed'
  | 'NotSent'
  | 'PartiallySent'
  | 'Sending'
  | 'Sent';

export type InvoiceSettlementStatus =
  | 'Paid'
  | 'PartiallyPaid'
  | 'Unpaid';

/**
 * How many invoices a billing period yields. Customer means one; every other
 * member means one per distinct value of that key.
 */
export type InvoiceSplitKey =
  | 'Customer'
  | 'CustomerAndDestination'
  | 'CustomerAndOrder'
  | 'CustomerAndOrigin'
  | 'CustomerAndPONumber'
  | 'CustomerAndServiceType'
  | 'CustomerAndShipmentBOL';

export type InvoiceStatus =
  | 'Draft'
  | 'Posted'
  /**
   * Taken out of circulation. The number and lines stay readable for the audit
   * trail; the open balance is zero and nothing is delivered.
   */
  | 'Voided';

/** What happens to the freight a voided invoice billed. */
export type InvoiceVoidDisposition =
  /** The billing queue items are canceled and the shipments settle as completed. */
  | 'DoNotRebill'
  /** The billing queue items go back to Approved with a fresh number, ready to bill again. */
  | 'Rebill';

